class Solution {
public:
    vector<vector<string>> findMismatchedSegments(string s1, string s2) {
        vector<vector<string>> res;
        int n = (int)s1.size();
        int i = 0;
        while (i < n) {
            if (s1[i] != s2[i]) {
                int start = i;
                while (i < n && s1[i] != s2[i]) {
                    ++i;
                }
                int len = i - start;
                res.push_back({s1.substr(start, len), s2.substr(start, len)});
            } else {
                ++i;
            }
        }
        return res;
    }
};
